def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        if history[0][1] == 'D':
            return 'D'
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_my = my[-1]
    last_opp = opp[-1]

    opp_def = sum(1 for a in opp if a == 'D')
    my_def = sum(1 for a in my if a == 'D')
    opp_c = n - opp_def
    opp_coop_rate = opp_c / n

    if n < 10:
        if opp_def > 0:
            return 'D'
        return 'C'

    retaliations = 0
    for i in range(n - 1):
        if my[i] == 'D' and opp[i + 1] == 'D':
            retaliations += 1
    if my_def > 0:
        ret_rate = retaliations / my_def
    else:
        ret_rate = 0.0

    if ret_rate > 0.6 and opp_coop_rate > 0.2:
        my_c_streak = 0
        for a in reversed(my):
            if a == 'C':
                my_c_streak += 1
            else:
                break
        if my_c_streak < 3:
            return 'C'

    if last_opp == 'D':
        if last_my == 'D':
            dd_streak = 0
            for i in range(n - 1, -1, -1):
                if my[i] == 'D' and opp[i] == 'D':
                    dd_streak += 1
                else:
                    break
            if dd_streak >= 2:
                if rng.random() < 0.5:
                    return 'C'
            return 'D'
        else:
            return 'D'

    if n >= 99:
        return 'D'
    if n >= 95:
        if ret_rate < 0.3:
            if n == 98:
                return 'D'
            if n == 97:
                return 'D' if rng.random() < 0.5 else 'C'
        return 'C'

    if my_def == 0:
        if n < 10:
            return 'C'
        else:
            return 'D'

    if ret_rate < 0.2:
        p = 0.7
    elif ret_rate < 0.4:
        p = 0.4
    elif ret_rate < 0.6:
        p = 0.1
    else:
        p = 0.0

    if last_my == 'D':
        return 'C'

    recent_opp_d = sum(1 for a in opp[-5:] if a == 'D')
    if recent_opp_d >= 2:
        return 'C'

    if rng.random() < p:
        return 'D'
    return 'C'
